package com.wizzadrds.theworldremembers.voice; public record SpatialVoice(double sourceX,double sourceY,double sourceZ,double maxDistance){public SpatialVoice{if(maxDistance<=0)throw new IllegalArgumentException("maxDistance");}public float volumeAt(double x,double y,double z){double d=Math.sqrt(Math.pow(x-sourceX,2)+Math.pow(y-sourceY,2)+Math.pow(z-sourceZ,2));return d>=maxDistance?0f:(float)Math.max(0,1-d/maxDistance);}}
